import React, { Component, ErrorInfo, ReactNode } from 'react';
import { Box, Typography } from '@mui/material';

interface Props {
	children?: ReactNode;
	errorMessage?: string;
}

interface State {
	hasError: boolean;
	fallback?: ReactNode;
}

class ErrorBoundaryGuard extends Component<Props, State> {
	public state: State = {
		hasError: false,
		fallback: null,
	};

	public static getDerivedStateFromError(_: Error): State {
		return { hasError: true };
	}

	public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
		console.error('Uncaught error:', error, errorInfo);
		this.setState((prevState) => ({ ...prevState, error: error.message }));
	}

	public render() {
		const { fallback } = this.state;
		const { errorMessage = 'Sorry.. there was an error' } = this.props;
		if (this.state.hasError) {
			return (
				<Box>
					<Typography variant={'body1'}>{fallback || errorMessage}</Typography>
				</Box>
			);
		}

		return this.props.children;
	}
}

export default ErrorBoundaryGuard;
